-- Precompute the small set of relay-domain observations as candidates arrive.
-- The view is tied to indicator asset 2026.09.21. When the asset changes,
-- create a new migration to replace this view and rebuild retained matches.
CREATE TABLE IF NOT EXISTS ai_relay_domain_matches_v1 (
 timestamp DateTime64(6,'UTC'), event_id String, sensor_id LowCardinality(String),
 campus_id LowCardinality(String), subject_ip String, domain String,
 source LowCardinality(String), indicator_version LowCardinality(String)
) ENGINE=MergeTree
PARTITION BY toDate(timestamp)
ORDER BY (timestamp,subject_ip,domain,event_id)
TTL toDateTime(timestamp)+INTERVAL 7 DAY DELETE;

CREATE MATERIALIZED VIEW IF NOT EXISTS ai_relay_domain_matches_v1_mv
TO ai_relay_domain_matches_v1 AS
SELECT timestamp,event_id,sensor_id,campus_id,subject_ip,domain,source,'2026.09.21' AS indicator_version
FROM (
 SELECT timestamp,event_id,sensor_id,campus_id,subject_ip,
  arrayJoin(arrayConcat([tuple('dns',dns_query),tuple(if(event_type='quic','quic','tls'),sni),tuple('http',http_host)],arrayMap(x -> tuple('handshake_tls',x),snis),arrayMap(x -> tuple('handshake_http',x),hosts))) AS candidate,
  lower(replaceRegexpOne(replaceRegexpOne(replaceRegexpOne(replaceRegexpOne(trimBoth(candidate.2),'^[a-zA-Z]+://',''),'^[*][.]',''),'[/:?#].*$',''),'[.]$','')) AS domain,
  candidate.1 AS source
 FROM ai_relay_domain_candidates_v1
 WHERE subject_ip!='' AND (multiSearchAnyCaseInsensitive(dns_query,['yunwu.ai','uiuiapi.com','dmxapi.cn','mkeai.com','gptgod.online','gptgod.cloud','xuanshuapi.com','teamorouter.com','wawazz.xyz','wappkit.com','relaydance.com','ai-router.dev','coderplan.ai','mnapi.com','bltcy.ai','rcouyi.com','closeai-asia.com','aigcbest.top','xjai.cc','gptapi.us','xeduapi.com','tomchat.fun','v3.cm','ephone.ai','nekoapi.com','openai-ch.top','paintbot.top','chatfire.cn','gu28.top','gptoai.cc','kfcv50.link','gueai.com','maynor1024.live','azapi.com.cn','openai-labs.com','zhtec.xyz','chienapi.top','sbgpt.site','ggwk1.online','aabao.top','gptuu.com','yuegle.com','kksj.org','nio.gs','onechats.top','api2d.com','ohmygpt.com','aiproxy.io','openai-hk.com','gptsapi.net','chatanywhere.tech','chatanywhere.com.cn','openrouter.ai','atlascloud.ai','aimlapi.com','routescope.ai','unorouter.ai','quicksilverpro.io','aiapi-pro.com','sandbase.ai','allrouter.ai','tokens-forge.com']) OR multiSearchAnyCaseInsensitive(sni,['yunwu.ai','uiuiapi.com','dmxapi.cn','mkeai.com','gptgod.online','gptgod.cloud','xuanshuapi.com','teamorouter.com','wawazz.xyz','wappkit.com','relaydance.com','ai-router.dev','coderplan.ai','mnapi.com','bltcy.ai','rcouyi.com','closeai-asia.com','aigcbest.top','xjai.cc','gptapi.us','xeduapi.com','tomchat.fun','v3.cm','ephone.ai','nekoapi.com','openai-ch.top','paintbot.top','chatfire.cn','gu28.top','gptoai.cc','kfcv50.link','gueai.com','maynor1024.live','azapi.com.cn','openai-labs.com','zhtec.xyz','chienapi.top','sbgpt.site','ggwk1.online','aabao.top','gptuu.com','yuegle.com','kksj.org','nio.gs','onechats.top','api2d.com','ohmygpt.com','aiproxy.io','openai-hk.com','gptsapi.net','chatanywhere.tech','chatanywhere.com.cn','openrouter.ai','atlascloud.ai','aimlapi.com','routescope.ai','unorouter.ai','quicksilverpro.io','aiapi-pro.com','sandbase.ai','allrouter.ai','tokens-forge.com']) OR multiSearchAnyCaseInsensitive(http_host,['yunwu.ai','uiuiapi.com','dmxapi.cn','mkeai.com','gptgod.online','gptg